/** Prepare the official workspace type contracts required to build this extension from a clean checkout. */

import { resolve } from 'node:path'
import { compileReferencedProjects, runPnpmCommand } from '../../../scripts/compile-referenced-projects.ts'

const root = resolve(import.meta.dirname, '../../..')

// DSH's remote declarations are generated by the Host bundler. Emit package
// declarations without semantic checks first, generate those contracts, then
// run the checked Host and Client project builds consumed by the extension.
compileReferencedProjects(root, 'host', 'benchmark-emit')
runPnpmCommand(root, ['exec', 'tsdown', '--config-loader', 'native', '--env.DSH_BUILD_FACE', 'host'])
compileReferencedProjects(root, 'host')
compileReferencedProjects(root, 'client')
